import React, { useEffect, useState } from "react";

import {
  AppBar,
  Toolbar,
  Typography,
  Container,
  Grid,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  TextField,
  Button,
  Select,
  MenuItem,
  Drawer,
  Box,
  Divider,
  List,
  ListItem,
  Avatar,
} from "@mui/material";

import {
  Warning,
  Error,
  CheckCircle,
} from "@mui/icons-material";

import axios from "axios";

const Dashboard = () => {

  const [buyers, setBuyers] = useState([]);

  const [search, setSearch] = useState("");

  const [riskFilter, setRiskFilter] =
    useState("ALL");

  const [vpnOnly, setVpnOnly] =
    useState(false);

  const [promoOnly, setPromoOnly] =
    useState(false);

  const [selectedBuyer, setSelectedBuyer] =
    useState(null);

  const [drawerOpen, setDrawerOpen] =
    useState(false);

  useEffect(() => {
    fetchBuyers();
  }, []);

  const fetchBuyers = async () => {
    try {

      const response = await axios.get(
        "http://localhost:8000/buyers"
      );

      setBuyers(response.data);

    } catch (error) {

      console.error(
        "Error fetching buyers",
        error
      );

    }
  };

  const openBuyerDrawer = (buyer) => {
    setSelectedBuyer(buyer);
    setDrawerOpen(true);
  };

  const closeDrawer = () => {
    setDrawerOpen(false);
  };

  const generateRelationshipSignals = (
    buyer
  ) => {

    const signals = [];

    if (!buyer) return signals;

    if (buyer.shared_accounts >= 5) {
      signals.push(
        `${buyer.shared_accounts} buyers linked to same infrastructure`
      );
    }

    if (buyer.vpn_detected) {
      signals.push(
        "VPN / Proxy masking detected"
      );
    }

    if (buyer.return_ratio >= 50) {
      signals.push(
        "Abnormally high return behavior"
      );
    }

    if (buyer.orders_last_24h >= 10) {
      signals.push(
        "High velocity ordering pattern"
      );
    }

    if (buyer.promo_abuse) {
      signals.push(
        "Promo abuse ring suspected"
      );
    }

    if (
      buyer.address_quality ===
      "GARBLED"
    ) {
      signals.push(
        "Synthetic / manipulated address"
      );
    }

    return signals;
  };

  const filteredBuyers = buyers.filter(
    (buyer) => {

      const matchesSearch =
        buyer.name
          .toLowerCase()
          .includes(
            search.toLowerCase()
          );

      const matchesRisk =
        riskFilter === "ALL"
          ? true
          : buyer.risk_level ===
            riskFilter;

      const matchesVpn =
        vpnOnly
          ? buyer.vpn_detected === true
          : true;

      const matchesPromo =
        promoOnly
          ? buyer.promo_abuse === true
          : true;

      return (
        matchesSearch &&
        matchesRisk &&
        matchesVpn &&
        matchesPromo
      );
    }
  );

  const lowRiskCount = buyers.filter(
    (b) => b.risk_level === "GREEN"
  ).length;

  const mediumRiskCount = buyers.filter(
    (b) => b.risk_level === "AMBER"
  ).length;

  const highRiskCount = buyers.filter(
    (b) => b.risk_level === "RED"
  ).length;

  return (
    <div
      style={{
        background: "#f4f6f8",
        minHeight: "100vh",
      }}
    >

      <AppBar
        position="static"
        sx={{
          background:
            "#081330",
        }}
      >

        <Toolbar>

          <Avatar
            sx={{
              marginRight: 2,
            }}
          >
            R
          </Avatar>

          <Typography variant="h5">
            Ecommerce Buyer Risk Dashboard
          </Typography>

        </Toolbar>

      </AppBar>

      <Container
        maxWidth="xl"
        sx={{
          marginTop: 4,
        }}
      >

        <Grid
          container
          spacing={3}
        >

          <Grid item xs={12} md={3}>
            <Card
              sx={{
                borderRadius: 4,
              }}
            >
              <CardContent>

                <Typography variant="h5">
                  Low Risk Buyers
                </Typography>

                <Typography
                  variant="h2"
                >
                  {lowRiskCount}
                </Typography>

                <CheckCircle
                  color="success"
                  fontSize="large"
                />

              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={3}>
            <Card
              sx={{
                borderRadius: 4,
              }}
            >
              <CardContent>

                <Typography variant="h5">
                  Medium Risk Buyers
                </Typography>

                <Typography
                  variant="h2"
                >
                  {mediumRiskCount}
                </Typography>

                <Warning
                  color="warning"
                  fontSize="large"
                />

              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={3}>
            <Card
              sx={{
                borderRadius: 4,
              }}
            >
              <CardContent>

                <Typography variant="h5">
                  High Risk Buyers
                </Typography>

                <Typography
                  variant="h2"
                >
                  {highRiskCount}
                </Typography>

                <Error
                  color="error"
                  fontSize="large"
                />

              </CardContent>
            </Card>
          </Grid>

        </Grid>

        <Card
          sx={{
            marginTop: 5,
            borderRadius: 5,
            padding: 2,
          }}
        >

          <CardContent>

            <Typography
              variant="h4"
              sx={{
                marginBottom: 3,
              }}
            >
              Buyer Investigation Queue
            </Typography>

            <Box
              display="flex"
              gap={2}
              flexWrap="wrap"
              marginBottom={3}
            >

              <TextField
                label="Search buyer"
                variant="outlined"
                value={search}
                onChange={(e) =>
                  setSearch(
                    e.target.value
                  )
                }
              />

              <Select
                value={riskFilter}
                onChange={(e) =>
                  setRiskFilter(
                    e.target.value
                  )
                }
                sx={{
                  minWidth: 130,
                }}
              >

                <MenuItem value="ALL">
                  ALL
                </MenuItem>

                <MenuItem value="RED">
                  RED
                </MenuItem>

                <MenuItem value="AMBER">
                  AMBER
                </MenuItem>

                <MenuItem value="GREEN">
                  GREEN
                </MenuItem>

              </Select>

              <Button
                variant={
                  vpnOnly
                    ? "contained"
                    : "outlined"
                }
                color="error"
                onClick={() =>
                  setVpnOnly(
                    !vpnOnly
                  )
                }
              >
                VPN BUYERS
              </Button>

              <Button
                variant={
                  promoOnly
                    ? "contained"
                    : "outlined"
                }
                color="warning"
                onClick={() =>
                  setPromoOnly(
                    !promoOnly
                  )
                }
              >
                PROMO ABUSE
              </Button>

              <Button
                variant="outlined"
                color="secondary"
                onClick={() => {

                  setRiskFilter(
                    "ALL"
                  );

                  setVpnOnly(false);

                  setPromoOnly(
                    false
                  );

                  setSearch("");

                }}
              >
                RESET FILTERS
              </Button>

            </Box>

            <TableContainer
              component={Paper}
            >

              <Table>

                <TableHead>

                  <TableRow>

                    <TableCell>
                      Buyer ID
                    </TableCell>

                    <TableCell>
                      Name
                    </TableCell>

                    <TableCell>
                      Risk
                    </TableCell>

                    <TableCell>
                      IP Address
                    </TableCell>

                    <TableCell>
                      Fingerprint
                    </TableCell>

                    <TableCell>
                      Shared Accounts
                    </TableCell>

                    <TableCell>
                      Return Ratio
                    </TableCell>

                    <TableCell>
                      Orders 24H
                    </TableCell>

                    <TableCell>
                      Address
                    </TableCell>

                    <TableCell>
                      VPN
                    </TableCell>

                    <TableCell>
                      Promo Abuse
                    </TableCell>

                    <TableCell>
                      Delivery Failures
                    </TableCell>

                  </TableRow>

                </TableHead>

                <TableBody>

                  {filteredBuyers.map(
                    (buyer) => (

                      <TableRow
                        key={buyer.id}
                        hover
                        onClick={() =>
                          openBuyerDrawer(
                            buyer
                          )
                        }
                        sx={{
                          cursor:
                            "pointer",
                        }}
                      >

                        <TableCell>
                          {buyer.id}
                        </TableCell>

                        <TableCell>
                          {buyer.name}
                        </TableCell>

                        <TableCell>

                          <Chip
                            label={
                              buyer.risk_level
                            }
                            color={
                              buyer.risk_level ===
                              "RED"
                                ? "error"
                                : buyer.risk_level ===
                                  "AMBER"
                                ? "warning"
                                : "success"
                            }
                          />

                        </TableCell>

                        <TableCell>
                          {
                            buyer.ip_address
                          }
                        </TableCell>

                        <TableCell>
                          {
                            buyer.device_fingerprint
                          }
                        </TableCell>

                        <TableCell>

                          <Chip
                            label={
                              buyer.shared_accounts
                            }
                            color={
                              buyer.shared_accounts >=
                              5
                                ? "error"
                                : "success"
                            }
                          />

                        </TableCell>

                        <TableCell>

                          <Chip
                            label={`${buyer.return_ratio}%`}
                            color={
                              buyer.return_ratio >=
                              50
                                ? "error"
                                : buyer.return_ratio >=
                                  20
                                ? "warning"
                                : "success"
                            }
                          />

                        </TableCell>

                        <TableCell>

                          <Chip
                            label={
                              buyer.orders_last_24h
                            }
                            color={
                              buyer.orders_last_24h >=
                              10
                                ? "error"
                                : buyer.orders_last_24h >=
                                  5
                                ? "warning"
                                : "success"
                            }
                          />

                        </TableCell>

                        <TableCell>

                          <Chip
                            label={
                              buyer.address_quality
                            }
                            color={
                              buyer.address_quality ===
                              "GARBLED"
                                ? "error"
                                : "success"
                            }
                          />

                        </TableCell>

                        <TableCell>

                          <Chip
                            label={
                              buyer.vpn_detected
                                ? "Detected"
                                : "Clean"
                            }
                            color={
                              buyer.vpn_detected
                                ? "error"
                                : "success"
                            }
                          />

                        </TableCell>

                        <TableCell>

                          <Chip
                            label={
                              buyer.promo_abuse
                                ? "Yes"
                                : "No"
                            }
                            color={
                              buyer.promo_abuse
                                ? "warning"
                                : "success"
                            }
                          />

                        </TableCell>

                        <TableCell>

                          <Chip
                            label={
                              buyer.delivery_failures
                            }
                            color={
                              buyer.delivery_failures >=
                              3
                                ? "error"
                                : buyer.delivery_failures >=
                                  1
                                ? "warning"
                                : "success"
                            }
                          />

                        </TableCell>

                      </TableRow>

                    )
                  )}

                </TableBody>

              </Table>

            </TableContainer>

          </CardContent>

        </Card>

      </Container>

      <Drawer
        anchor="right"
        open={drawerOpen}
        onClose={closeDrawer}
      >

        <Box
          sx={{
            width: 420,
            padding: 3,
          }}
        >

          {selectedBuyer && (

            <>

              <Typography
                variant="h4"
                gutterBottom
              >
                {selectedBuyer.name}
              </Typography>

              <Chip
                label={
                  selectedBuyer.risk_level
                }
                color={
                  selectedBuyer.risk_level ===
                  "RED"
                    ? "error"
                    : selectedBuyer.risk_level ===
                      "AMBER"
                    ? "warning"
                    : "success"
                }
                sx={{
                  marginBottom: 2,
                }}
              />

              <Divider
                sx={{
                  marginTop: 2,
                  marginBottom: 2,
                }}
              />

              <Typography
                variant="h6"
                sx={{
                  marginBottom: 1,
                }}
              >
                Linked Fraud Intelligence
              </Typography>

              <List>

                {generateRelationshipSignals(
                  selectedBuyer
                ).length > 0 ? (

                  generateRelationshipSignals(
                    selectedBuyer
                  ).map(
                    (
                      signal,
                      index
                    ) => (

                      <ListItem
                        key={index}
                      >

                        <Chip
                          label={
                            signal
                          }
                          color="error"
                          sx={{
                            width:
                              "100%",
                          }}
                        />

                      </ListItem>

                    )
                  )

                ) : (

                  <Typography variant="body2">
                    No linked fraud signals
                    detected.
                  </Typography>

                )}

              </List>

              <Divider
                sx={{
                  marginTop: 2,
                  marginBottom: 2,
                }}
              />

              <Typography
                variant="h6"
              >
                Investigator Summary
              </Typography>

              <Typography
                variant="body1"
                sx={{
                  marginTop: 2,
                }}
              >
                IP Address:
                {" "}
                {
                  selectedBuyer.ip_address
                }
              </Typography>

              <Typography
                variant="body1"
              >
                Device Fingerprint:
                {" "}
                {
                  selectedBuyer.device_fingerprint
                }
              </Typography>

              <Typography
                variant="body1"
              >
                Google App Instance ID:
                {" "}
                {
                  selectedBuyer.google_app_instance_id
                }
              </Typography>

              <Typography
                variant="body1"
              >
                Shared Accounts:
                {" "}
                {
                  selectedBuyer.shared_accounts
                }
              </Typography>

              <Typography
                variant="body1"
              >
                Return Ratio:
                {" "}
                {
                  selectedBuyer.return_ratio
                }
                %
              </Typography>

              <Typography
                variant="body1"
              >
                Orders Last 24H:
                {" "}
                {
                  selectedBuyer.orders_last_24h
                }
              </Typography>

              <Typography
                variant="body1"
              >
                Address Quality:
                {" "}
                {
                  selectedBuyer.address_quality
                }
              </Typography>

              <Typography
                variant="body1"
              >
                VPN Detected:
                {" "}
                {selectedBuyer.vpn_detected
                  ? "YES"
                  : "NO"}
              </Typography>

              <Typography
                variant="body1"
              >
                Promo Abuse:
                {" "}
                {selectedBuyer.promo_abuse
                  ? "YES"
                  : "NO"}
              </Typography>

              <Typography
                variant="body1"
              >
                Delivery Failures:
                {" "}
                {
                  selectedBuyer.delivery_failures
                }
              </Typography>

            </>

          )}

        </Box>

      </Drawer>

    </div>
  );
};

export default Dashboard;
